package dev.morphe.engine;

/**
 * Represents the phases of the Morphe compilation and execution pipeline.
 */
public enum EnginePhase {

  /**
   * Lexical analysis of the source code.
   */
  LEXING,

  /**
   * Syntactic analysis of the token stream.
   */
  PARSING,

  /**
   * Semantic analysis of the abstract syntax tree.
   */
  SEMANTIC_ANALYSIS,

  /**
   * Compilation of the semantically valid AST into bytecode.
   */
  COMPILATION,

  /**
   * Execution of the generated bytecode.
   */
  EXECUTION
}